// One word from words.txt and its clue
class WordClue
{
    public string Word { get; set; }   // the word, in capitals
    public string Clue { get; set; }   // a one-sentence clue

    // Makes one WordClue from a line of words.txt, split at each |
    public WordClue(string[] parts)
    {
        Word = parts[0];
        Clue = parts[1];
    }

    // Reads every word in words.txt into a list
    public static List<WordClue> LoadAll()
    {
        List<WordClue> words = new List<WordClue>();
        string path = Files.Data("words.txt");
        if (!File.Exists(path)) return words;   // no file: an empty list
        StreamReader reader = new StreamReader(path);
        while (!reader.EndOfStream)
        {
            string line = reader.ReadLine();
            string[] parts = line.Split('|');
            if (parts.Length != 2) continue;    // skip a broken line
            words.Add(new WordClue(parts));
        }
        reader.Close();
        return words;
    }
}

// ---------- the game-form methods from chapter 9 ----------

// Keeps the result on the map, even if the window is then closed
private void KeepResult()
{
    Expedition.Finish(gameNumber, result);
    finished = true;
    lblScore.Text = "Points: " + result.Score;
}

// Fills in the Round over panel and brings it to the front
private void ShowRoundOver()
{
    lblRoundScore.Text = "You scored " + result.Score
        + " out of 100 points.";
    lblWellList.Text = ListText(result.WentWell,
        "thing that went well", "things that went well");
    lblWrongList.Text = ListText(result.WentWrong,
        "thing that went wrong", "things that went wrong");
    if (result.Score >= 60) Sound.Play("win.wav");
    else Sound.Play("lose.wav");
    pnlRoundOver.Visible = true;
    pnlRoundOver.BringToFront();
}

// Up to 3 lines from a list, then how many more there are
private string ListText(List<string> lines, string one, string many)
{
    if (lines.Count == 0) return "Nothing this time.";
    string text = "";
    for (int i = 0; i < lines.Count && i < 3; i++)
    {
        text = text + "- " + lines[i] + Environment.NewLine;
    }
    int more = lines.Count - 3;
    if (more == 1) text = text + "And 1 more " + one + ".";
    if (more > 1) text = text + "And " + more + " more " + many + ".";
    return text;
}

// Back to the map: closing the window runs FormClosing
private void btnBack_Click(object sender, EventArgs e)
{
    this.Close();
}

// The Round over panel's Back to the map button
private void btnDone_Click(object sender, EventArgs e)
{
    this.Close();
}

// Runs as the window closes, by Back, by Done or by the X
private void frmWhiteout_FormClosing(object sender,
    FormClosingEventArgs e)
{
    if (finished) return;    // a finished round closes at once
    DialogResult answer = MessageBox.Show("Leave Whiteout? It will "
        + "score nothing, but you can come back and climb it again.",
        "Summit Ready", MessageBoxButtons.YesNo);
    if (answer == DialogResult.No) e.Cancel = true;   // stay
}

// Shows the speaker picture that matches the sound being on or off
private void ShowSpeaker()
{
    string icon = "icon-speaker-on-64.png";
    if (Sound.Muted) icon = "icon-speaker-muted-64.png";
    picSound.Image = Files.Picture("Icons", icon);
}

// The speaker picture turns the sound off, or back on
private void picSound_Click(object sender, EventArgs e)
{
    Sound.Muted = !Sound.Muted;
    ShowSpeaker();
}

// ---------- Whiteout ----------
private List<WordClue> words;          // every word in words.txt
private int[] order;                   // the words, mixed up
private int number = 0;                // this word, 0 to 3
private string word;                   // the word being guessed
private char[] found;                  // letters found, '_' if not
private string tried = "";             // every letter tried so far
private int wrong = 0;                 // wrong letters on this word
private bool wordOver = false;         // true once solved or lost
private int total = 0;                 // points from every word
private Button[] letters = new Button[26];
private List<string> wellLines = new List<string>();
private List<string> wrongLines = new List<string>();

private void frmWhiteout_Load(object sender, EventArgs e)
{
    // Runs once, right before the window first appears
    ShowSpeaker();
    picPeak.Image = Files.Picture("Summits", "summit-bearnagh.jpg");
    pnlFog.BackgroundImage = Files.Picture("", "fog.jpg");
    MakeLetters();
    words = WordClue.LoadAll();
    if (words.Count < 4)
    {
        lblClue.Text = "Whiteout needs 4 words in Data\\words.txt, "
            + "each written as WORD|clue.";
        return;
    }
    order = Mix.ShuffledNumbers(words.Count);
    ShowWord();
}

// Makes the 26 letter buttons, A to Z, in two rows of 13
private void MakeLetters()
{
    for (int i = 0; i < 26; i++)
    {
        Button b = new Button();
        b.Text = ((char)('A' + i)).ToString();
        b.Size = new Size(44, 44);
        b.Margin = new Padding(3);
        b.FlatStyle = FlatStyle.Flat;
        b.BackColor = Color.White;
        b.ForeColor = Color.FromArgb(38, 50, 56);
        b.Font = new Font("Segoe UI Semibold", 12);
        b.Cursor = Cursors.Hand;
        b.Click += Letter_Click;
        letters[i] = b;
        flpLetters.Controls.Add(b);
        if (i == 12) flpLetters.SetFlowBreak(b, true);
    }
}

// Puts the next word on the screen with every letter hidden
private void ShowWord()
{
    word = words[order[number]].Word.ToUpper();
    lblClue.Text = words[order[number]].Clue;
    lblWordCount.Text = "Word " + (number + 1) + " of 4";
    found = new char[word.Length];
    for (int i = 0; i < word.Length; i++)
    {
        found[i] = '_';
    }
    tried = "";
    wrong = 0;
    wordOver = false;
    pnlFog.Height = 0;
    lblWord.ForeColor = Color.FromArgb(38, 50, 56);
    lblWrong.Text = "Wrong letters: 0 of 6";
    lblMessage.Text = "";

    btnNext.Visible = false;
    for (int i = 0; i < 26; i++)
    {
        letters[i].Enabled = true;
        letters[i].BackColor = Color.White;
    }
    ShowFound();
}

// Writes the letters found so far, with a space between each one
private void ShowFound()
{
    string shown = "";
    for (int i = 0; i < found.Length; i++)
    {
        if (i > 0) shown = shown + " ";
        shown = shown + found[i];
    }
    lblWord.Text = shown;
}

// A letter button was clicked
private void Letter_Click(object sender, EventArgs e)
{
    Button b = (Button)sender;
    TryLetter(b.Text[0]);
}

// A key was typed: KeyPreview lets the form hear it first
private void frmWhiteout_KeyPress(object sender, KeyPressEventArgs e)
{
    char letter = char.ToUpper(e.KeyChar);
    if (letter < 'A' || letter > 'Z') return;   // not a letter
    e.Handled = true;
    try
    {
        TryLetter(letter);
    }
    catch (LetterAlreadyTriedException ex)
    {
        lblMessage.Text = ex.Message;   // costs nothing
    }
}

// Checks one letter against the word
private void TryLetter(char letter)
{
    if (wordOver || word == null) return;
    if (tried.IndexOf(letter) >= 0)
    {
        throw new LetterAlreadyTriedException(letter);
    }
    tried = tried + letter;
    letters[letter - 'A'].Enabled = false;
    // A flat button looks the same when off, so grey it
    letters[letter - 'A'].BackColor = Color.FromArgb(207, 216, 220);
    lblMessage.Text = "";
    bool inWord = false;
    for (int i = 0; i < word.Length; i++)
    {
        if (word[i] == letter)
        {
            found[i] = letter;
            inWord = true;
        }
    }

    if (inWord)
    {
        Sound.Play("key.wav");
        ShowFound();
        if (new string(found) == word) WordSolved();
    }
    else
    {
        wrong++;
        Sound.Play("whoosh.wav");
        pnlFog.Height = wrong * 60;    // the cloud comes down
        lblWrong.Text = "Wrong letters: " + wrong + " of 6";
        if (wrong == 6) Whiteout();
    }
}

// Points for one word: 25 take away 4 for each wrong letter
private int WordPoints()
{
    if (wrong == 6) return 0;
    int points = 25 - 4 * wrong;
    if (points < 5) points = 5;
    return points;
}

// The whole word is found
private void WordSolved()
{
    int points = WordPoints();
    total = total + points;
    lblWord.ForeColor = Color.FromArgb(62, 142, 65);
    lblMessage.Text = "You found the word " + word + ". It scores "
        + points + " points.";
    if (wrong == 1)
    {
        wellLines.Add("You found " + word + " with 1 wrong letter.");
    }
    else
    {
        wellLines.Add("You found " + word + " with " + wrong
            + " wrong letters.");
    }
    Sound.Play("correct.wav");
    EndWord();
}

// The sixth wrong letter: the cloud hides the mountain
private void Whiteout()
{
    for (int i = 0; i < word.Length; i++)
    {
        found[i] = word[i];
    }
    ShowFound();
    lblWord.ForeColor = Color.FromArgb(178, 58, 46);
    lblMessage.Text = "Whiteout! The word was " + word + ".";
    wrongLines.Add("The cloud came down on " + word + ".");
    Sound.Play("lose.wav");
    EndWord();
}

// Stops this word and shows the Next word button
private void EndWord()
{
    wordOver = true;
    for (int i = 0; i < 26; i++)
    {
        letters[i].Enabled = false;
    }
    if (number == 3)
    {
        btnNext.Text = "See my score";
        RecordResult();
    }
    else
    {
        btnNext.Text = "Next word";
    }
    lblScore.Text = "Points: " + total;
    btnNext.Visible = true;
    btnNext.Focus();
}

// Next word, or See my score after word 4
private void btnNext_Click(object sender, EventArgs e)
{
    if (number == 3)
    {
        ShowRoundOver();
        return;
    }
    number++;
    ShowWord();
}

// Adds the feedback to the result, then keeps it
private void RecordResult()
{
    result = new GameResult("Whiteout", total);
    result.WentWell.AddRange(wellLines);
    result.WentWrong.AddRange(wrongLines);
    KeepResult();
}
